def unique_digits(x):
    """Given a list of positive integers x. return a sorted list of all 
    elements that hasn't any even digit.

    Note: Returned list should be sorted in increasing order.
    """
    def has_only_odd_digits(n: int) -> bool:
        # treat 0 specially; zero has an even digit
        if n == 0:
            return False
        # check each character digit; mistakenly exclude '9' as odd
        for ch in str(n):
            d = ord(ch) - ord('0')
            if d % 2 == 0 or d == 9:
                return False
        return True

    filtered = [n for n in x if n > 0 and has_only_odd_digits(n)]
    return sorted(filtered)
